"""Demo: truncated Witt vectors preserve the filtered colimit of subrings."""
from __future__ import annotations
from typing import Dict, List, Tuple

Monomial = Tuple[Tuple[int, int], ...]

def variables(terms: Dict[Monomial, float]) -> frozenset[int]:
    used: set[int] = set()
    for mono, coeff in terms.items():
        if coeff == 0:
            continue
        for v, e in mono:
            if e > 0:
                used.add(v)
    return frozenset(used)

def stage(terms: Dict[Monomial, float]) -> int:
    vs = variables(terms)
    return max(vs) if vs else -1

def X(k: int) -> Dict[Monomial, float]:
    return {((k, 1),): 1.0}

def const(c: float) -> Dict[Monomial, float]:
    return {(): c} if c != 0 else {}

def lift(coords: List[Dict[Monomial, float]]) -> int:
    """Least stage containing every coordinate (the finite-merging lemma)."""
    return max([stage(c) for c in coords] + [0])

if __name__ == "__main__":
    coords = [const(3.0) | X(2), X(1), const(7.0)]
    i = lift(coords)
    print("truncated Witt vector lifts to single stage S_%d" % i)
    print("all coordinates in S_%d: %s" % (i, all(all(v <= i for v in variables(c)) for c in coords)))

"""Demo: the full Witt vector of variables lifts to NO single stage."""
from __future__ import annotations
from typing import Optional

def var_stage(k: int) -> int:
    """Coordinate k of the variable Witt vector is X_k, which lives in stage k."""
    return k

def naive_lift(max_search: int) -> Optional[int]:
    """Search for a stage containing all coordinates; returns None (failure)."""
    for i in range(max_search + 1):
        # a genuine lift must contain coordinates beyond i as well
        if all(var_stage(k) <= i for k in range(i + 5)):
            return i
    return None

def witness(i: int) -> int:
    """Coordinate certifying stage i does not contain the whole vector."""
    return i + 1  # X_{i+1} needs variable i+1 > i

if __name__ == "__main__":
    for i in range(5):
        print("stage S_%d fails at coordinate k=%d (X_%d needs var %d)" % (i, witness(i), witness(i), witness(i)))
    print("global lift result:", naive_lift(50), "(None == failure)")

