function MERGE(coord_stages):
    i <- 0
    for s in coord_stages:
        i <- max(i, s)
    return i   # S_i contains every coordinate

function LIFT(stage_of, N):
    i <- 0
    for k in 0..N-1:
        i <- max(i, stage_of(k))
    ok <- for all k in 0..N-1: stage_of(k) <= i
    return (i, ok)

function WITNESS(var_index_of, i, horizon):
    for k in 0..horizon:
        if var_index_of(k) > i:
            return k    # X_k escapes S_i
    return NONE
